 return['request_id'=>clean($d['request_id']??'',100),'nombre'=>clean($d['name']??'',120),'empresa'=>clean($d['company']??'',160),'rol'=>$role,'rubro'=>$industry,'email'=>strtolower(clean($d['email']??'',180)),'whatsapp'=>$whatsapp,'web'=>$web,'linkedin'=>clean($d['linkedin']??'',300),'problema'=>$problem,'consentimiento'=>!empty($d['accepted'])?'si':'','website_check'=>clean($d['website_check']??'',100),'origen'=>'Web','campania'=>$campaign,'utm_source'=>$utmSource,'utm_medium'=>safe_code($attr['medium']??'',100),'utm_campaign'=>safe_code($attr['campaign']??'',100)?:$campaign,'utm_content'=>clean(($type==='quiz'?'quiz|':'direct|').'intent='.$intent.'|locale='.$locale,200),'page_url'=>'https://sinecdo.com'.clean($attr['path']??($type==='quiz'?'/quest/':'/'),300)];}
function call_legacy(array $payload):bool{$endpoint='https://script.google.com/macros/s/AKfycbzM62i0CqEVCqH7oxFj3wBsjqB0Ry2Pza6Zi9e5jUiUGwi4OD-S_pArMURvk62qdxQL1A/exec';if(!function_exists('curl_init'))return false;$ch=curl_init($endpoint);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query($payload),CURLOPT_HTTPHEADER=>['Content-Type: application/x-www-form-urlencoded;charset=UTF-8'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,CURLOPT_TIMEOUT=>25,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_REDIR_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_USERAGENT=>'SinecdoWeb/2026-09-16']);$result=curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);return is_string($result)&&$http===200&&parse_legacy_response($result,(string)$payload['request_id']);}
function call_secure_receiver(array $cfg,string $raw,array $data):?array{$secret=(string)($cfg['relay_secret']??'');$endpoint=(string)($cfg['apps_script_url']??'');if(($cfg['enabled']??false)!==true||($cfg['privacy_approved']??false)!==true)return null;if(strlen($secret)<32||!preg_match('~^https://script\.google\.com/macros/s/[A-Za-z0-9_-]+/exec$~',$endpoint)||!function_exists('curl_init'))return null;$ts=(string)time();$envelope=json_encode(['timestamp'=>$ts,'payload'=>$raw,'signature'=>hash_hmac('sha256',$ts.'.'.$raw,$secret)]);$ch=curl_init($endpoint);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$envelope,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>3,CURLOPT_TIMEOUT=>25,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_REDIR_PROTOCOLS=>CURLPROTO_HTTPS]);$result=curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if(!is_string($result)||$http!==200)return null;$out=json_decode($result,true);if(!is_array($out))return null;if(($out['ok']??false)===true&&($out['request_id']??'')===($data['request_id']??'')&&preg_match('/^REG-[a-zA-Z0-9-]{16,80}$/',(string)($out['receipt']??'')))return['ok'=>true,'request_id'=>$out['request_id'],'receipt'=>$out['receipt'],'version'=>$out['version']??''];return['ok'=>false,'code'=>(string)($out['code']??'server')];}
if(($_SERVER['REQUEST_METHOD']??'')!=='POST'){header('Allow: POST');reply(405,['ok'=>false,'code'=>'method']);}if(strtolower(explode(';',$_SERVER['CONTENT_TYPE']??'')[0])!=='application/json')reply(415,['ok'=>false,'code'=>'content_type']);if((int)($_SERVER['CONTENT_LENGTH']??0)>20000)reply(413,['ok'=>false,'code'=>'too_large']);$raw=file_get_contents('php://input',false,null,0,20001);if($raw===false||strlen($raw)>20000)reply(413,['ok'=>false,'code'=>'too_large']);$data=json_decode($raw,true);if(!is_array($data)||!empty($data['website_check']))reply(400,['ok'=>false,'code'=>'invalid']);
$requestId=clean($data['request_id']??'',100);$type=clean($data['type']??'',20);$locale=clean($data['locale']??'',5);$name=clean($data['name']??'',120);$email=strtolower(clean($data['email']??'',180));$company=clean($data['company']??'',160);if(!preg_match('/^[a-f0-9-]{20,100}$/i',$requestId)||!in_array($type,['quiz','direct'],true)||!in_array($locale,['es','en','it'],true)||$name===''||$company===''||!valid_email($email)||empty($data['accepted']))reply(400,['ok'=>false,'code'=>'invalid']);if($type==='direct'){foreach(['role','industry','web','whatsapp','problem']as$required)if(clean($data[$required]??'')==='')reply(400,['ok'=>false,'code'=>'invalid']);}
$runtime=runtime_dir();$fingerprint=hash('sha256',$raw);$journalPath=$runtime!==''?$runtime.'/req-'.hash('sha256',$requestId).'.json':'';if($journalPath!==''){$previous=json_file_read($journalPath);if(is_array($previous)){if(($previous['fingerprint']??'')!==$fingerprint)reply(409,['ok'=>false,'code'=>'conflict']);if(!empty($previous['receipt']))reply(200,['ok'=>true,'request_id'=>$requestId,'receipt'=>$previous['receipt'],'version'=>$previous['version']??'legacy-bridge-1']);}}
$cfgPath=getenv('SINECDO_CONFIG')?:(rtrim((string)($_SERVER['DOCUMENT_ROOT']??''),'/').'/../sinecdo-private/intake-config.php');if(is_file($cfgPath)){$cfg=require$cfgPath;if(is_array($cfg)){$secure=call_secure_receiver($cfg,$raw,$data);if(is_array($secure)&&($secure['ok']??false)===true){if($journalPath!=='')json_file_write($journalPath,['fingerprint'=>$fingerprint,'receipt'=>$secure['receipt'],'version'=>$secure['version']??'secure']);reply(200,$secure);}if(is_array($secure)&&isset($secure['code'])&&$secure['code']==='conflict')reply(409,['ok'=>false,'code'=>'conflict']);}}
